return [
  {
    json: {
      request: {
        model: "sonar",
        messages: [
          {
            role: "system",
            content:
              "You are a social media assistant summarizing tech news for Twitter/X. Only return one article. Your output must follow this exact format: a short, engaging headline (max 140 characters), followed by a single space, then the direct article link. Do not use markdown, hashtags, emojis, or line breaks. Keep the total output under 200 characters. Be precise, objective, and newsworthy.",
          },
          { role: "user", content: "What's the latest news in artificial intelligence?" },
        ],
        temperature: 0.3,
        top_p: 0.9,
        return_citations: true,
        search_domain_filter: ["perplexity.ai"],
        search_recency_filter: "day",
        return_images: true,
        return_related_questions: false,
        max_tokens: 80,
        stream: false,
        presence_penalty: 0,
        frequency_penalty: 1,
      },
    },
  },
];

function message({ response }) {
  const text = response?.choices?.[0]?.message?.content;
  if (
    typeof text !== "string" ||
    !text.trim() ||
    [...text].length > 200 ||
    !/^\S[\s\S]*https?:\/\/\S+/i.test(text.trim())
  )
    throw Error("Expected a short headline and article link");
  return { text: text.trim() };
}

return { json: message({ response: $json }) };
